/** Media3 owns decoding, source seeking and the playback clock. WebView never opens video files. */
final class NativePlayback59 {
 final MainActivity owner;final FrameLayout deck;final Handler main=new Handler(Looper.getMainLooper());final LinkedHashMap<String,Session> sessions=new LinkedHashMap<>();
 final class Session {String id,mediaId,error;TextureView view;ExoPlayer player;volatile long frameUs=-1;boolean first,hasVideo;int width=640,height=360;Session(String id,String mediaId)throws Exception{this.id=id;this.mediaId=mediaId;hasVideo=probe(mediaId).getString("kind").equals("video");view=new TextureView(owner);deck.addView(view,new FrameLayout.LayoutParams(640,360));player=new ExoPlayer.Builder(owner).build();player.setVideoTextureView(view);player.setSeekParameters(SeekParameters.EXACT);player.setVideoFrameMetadataListener((pts,release,format,mediaFormat)->{frameUs=pts;});player.addListener(new Player.Listener(){@Override public void onPlayerError(PlaybackException e){error=e.getErrorCodeName()+": "+e.getMessage();}@Override public void onVideoSizeChanged(VideoSize size){width=size.width;height=size.height;}@Override public void onRenderedFirstFrame(){first=true;}});player.setMediaItem(MediaItem.fromUri(Uri.fromFile(owner.mediaFile(mediaId))));player.prepare();}}
 NativePlayback59(MainActivity owner,FrameLayout deck){this.owner=owner;this.deck=deck;}
 JSONObject probe(String mediaId)throws Exception{MediaMetadataRetriever r=new MediaMetadataRetriever();try{r.setDataSource(owner.mediaFile(mediaId).getAbsolutePath());JSONObject result=new JSONObject();result.put("duration",Long.parseLong(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION))/1000.0);result.put("width",integer(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH)));result.put("height",integer(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_HEIGHT)));result.put("kind","yes".equals(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_HAS_VIDEO))?"video":"audio");result.put("rotation",integer(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_ROTATION)));result.put("decoder","Android Media3 / MediaCodec");return result;}finally{r.release();}}
 static int integer(String n){try{return Integer.parseInt(n);}catch(Exception e){return 0;}}
 void frame(String request,String sessionId,String mediaId,double time,boolean playing,double gain,boolean exporting){main.post(()->{try{if(!sessionId.matches("[A-Za-z0-9_-]{1,160}")||!Double.isFinite(time)||time<0||time>86400||!Double.isFinite(gain)||gain<0||gain>3)throw new IOException("Invalid playback request");Session s=sessions.get(sessionId);if(s==null||!s.mediaId.equals(mediaId)){if(s!=null)release(s);if(sessions.size()>=8){Session evict=sessions.values().stream().filter(x->!x.player.getPlayWhenReady()).findFirst().orElse(null);if(evict==null)throw new IOException("Too many simultaneously decoded media layers");sessions.remove(evict.id);release(evict);}s=new Session(sessionId,mediaId);sessions.put(sessionId,s);}final Session current=s;s.player.setVolume((float)Math.min(1,gain));long target=Math.round(time*1000),delta=Math.abs(s.player.getCurrentPosition()-target);boolean seek=delta>(playing?180:2);if(seek){s.frameUs=-1;s.first=false;s.player.seekTo(target);}s.player.setPlayWhenReady(playing);await(request,current,target,playing,exporting,SystemClock.elapsedRealtime()+10000);}catch(Exception e){owner.callback(request,null,e.getMessage());}});}
 void await(String request,Session s,long target,boolean playing,boolean exporting,long deadline){if(owner.isDestroyed())return;if(s.error!=null){owner.callback(request,null,s.error);return;}if(SystemClock.elapsedRealtime()>deadline){owner.callback(request,null,"Native decoder did not deliver a frame; "+s.player.getPlaybackState());return;}boolean video=s.hasVideo;boolean ready=s.player.getPlaybackState()==Player.STATE_READY||s.player.getPlaybackState()==Player.STATE_ENDED;if(ready&&(!video||s.frameUs>=Math.max(0,target*1000-100000)&&s.view.isAvailable())){if(!video){try{JSONObject data=new JSONObject();data.put("position",s.player.getCurrentPosition()/1000.0);owner.callback(request,data,null);}catch(Exception e){owner.callback(request,null,e.getMessage());}return;}main.postDelayed(()->capture(request,s,exporting),16);return;}main.postDelayed(()->await(request,s,target,playing,exporting,deadline),12);}
 void capture(String request,Session s,boolean exporting){try{int max=exporting?1920:720,w=s.width,h=s.height;double ratio=Math.min(1,(double)max/Math.max(w,h));w=Math.max(2,(int)(w*ratio));h=Math.max(2,(int)(h*ratio));Bitmap image=s.view.getBitmap(w,h);if(image==null)throw new IOException("Native decoded texture is not available");double position=s.player.getCurrentPosition()/1000.0;owner.frames59.execute(()->{try{ByteArrayOutputStream out=new ByteArrayOutputStream();image.compress(exporting?Bitmap.CompressFormat.PNG:Bitmap.CompressFormat.JPEG,92,out);JSONObject data=new JSONObject();data.put("image","data:image/"+(exporting?"png":"jpeg")+";base64,"+android.util.Base64.encodeToString(out.toByteArray(),android.util.Base64.NO_WRAP));data.put("position",position);data.put("width",image.getWidth());data.put("height",image.getHeight());owner.callback(request,data,null);}catch(Exception e){owner.callback(request,null,e.getMessage());}finally{image.recycle();}});}catch(Exception e){owner.callback(request,null,e.getMessage());}}
 void pause(){main.post(()->{for(Session s:sessions.values())s.player.pause();});}
 void active(String json){main.post(()->{try{Set<String> ids=new HashSet<>();JSONArray a=new JSONArray(json);for(int i=0;i<a.length();i++)ids.add(a.getString(i));for(Session s:sessions.values())if(!ids.contains(s.id))s.player.pause();}catch(Exception e){}});}
 void release(Session s){s.player.release();deck.removeView(s.view);}
 void close(){for(Session s:sessions.values())release(s);sessions.clear();}
}
